#define MAX_N 10000
#define MAX_PRIMES 2000

int primes[MAX_PRIMES];
int prime_count = 0;

// Sieve of Eratosthenes up to MAX_N
void sieve() {
    bool is_prime[MAX_N + 1];
    memset(is_prime, true, sizeof(is_prime));
    is_prime[0] = is_prime[1] = false;

    for (int i = 2; i * i <= MAX_N; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= MAX_N; j += i) {
                is_prime[j] = false;
            }
        }
    }

    for (int i = 2; i <= MAX_N; i++) {
        if (is_prime[i]) {
            primes[prime_count++] = i;
        }
    }
}

int count_representations(int n) {
    int count = 0;
    int sum = 0;
    int left = 0;

    for (int right = 0; right < prime_count; right++) {
        sum += primes[right];

        while (sum > n && left <= right) {
            sum -= primes[left];
            left++;
        }

        if (sum == n) {
            count++;
        }
    }

    return count;
}

