int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> queries;
    int n, mx = 0;
    while (cin >> n && n != 0) {
        queries.push_back(n);
        mx = max(mx, n);
    }

    if (queries.empty()) return 0;

    // Sieve of Eratosthenes
    vector<bool> isPrime(mx + 1, true);
    if (mx >= 0) isPrime[0] = false;
    if (mx >= 1) isPrime[1] = false;
    for (int i = 2; 1LL * i * i <= mx; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= mx; j += i) {
                isPrime[j] = false;
            }
        }
    }

    vector<int> primes;
    for (int i = 2; i <= mx; ++i) {
        if (isPrime[i]) primes.push_back(i);
    }

    // Prefix sums of primes
    int m = primes.size();
    vector<long long> pref(m + 1, 0);
    for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + primes[i];

    // Precompute counts for all possible sums up to mx
    vector<int> ways(mx + 1, 0);
    for (int i = 0; i < m; ++i) {
        for (int j = i + 1; j <= m; ++j) {
            long long sum = pref[j] - pref[i];
            if (sum > mx) break;
            ways[(int)sum]++;
        }
    }

    for (int x : queries) {
        cout << ways[x] << '\n';
    }

    return 0;
}

