public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<Integer> queries = new ArrayList<>();
        String line;
        int maxN = 0;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            int n = Integer.parseInt(line);
            if (n == 0) break;
            queries.add(n);
            if (n > maxN) maxN = n;
        }

        if (queries.isEmpty()) return;

        List<Integer> primes = sieve(maxN);

        StringBuilder out = new StringBuilder();
        for (int n : queries) {
            out.append(countWays(n, primes)).append('\n');
        }
        System.out.print(out.toString());
    }

    private static List<Integer> sieve(int n) {
        boolean[] isComposite = new boolean[n + 1];
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (!isComposite[i]) {
                primes.add(i);
                if ((long) i * i <= n) {
                    for (int j = i * i; j <= n; j += i) {
                        isComposite[j] = true;
                    }
                }
            }
        }
        return primes;
    }

    private static int countWays(int target, List<Integer> primes) {
        int count = 0;
        int left = 0, right = 0, sum = 0;
        int size = primes.size();

        while (true) {
            if (sum >= target) {
                if (sum == target) count++;
                sum -= primes.get(left++);
            } else {
                if (right == size) break;
                int p = primes.get(right);
                if (p > target && sum == 0) break;
                sum += p;
                right++;
            }
        }

        return count;
    }
}

