import sys
import math

def sieve(n: int):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    limit = int(math.isqrt(n))
    for i in range(2, limit + 1):
        if is_prime[i]:
            step = i
            start = i * i
            is_prime[start:n + 1:step] = [False] * (((n - start) // step) + 1)
    return [i for i in range(2, n + 1) if is_prime[i]]

def main():
    data = list(map(int, sys.stdin.read().split()))
    nums = []
    for x in data:
        if x == 0:
            break
        nums.append(x)

    if not nums:
        return

    max_n = max(nums)
    primes = sieve(max_n)

    out = []
    for n in nums:
        count = 0
        left = 0
        curr_sum = 0
        for right in range(len(primes)):
            curr_sum += primes[right]
            while curr_sum > n and left <= right:
                curr_sum -= primes[left]
                left += 1
            if curr_sum == n:
                count += 1
        out.append(str(count))

    sys.stdout.write("\n".join(out))

